def get_divisors(n):
    divs = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.append(i)
            if i * i != n:
                divs.append(n // i)
    divs.sort()
    return divs

def solve_problem():
    solutions = []
    N_MAX = 500

    for n in range(1, N_MAX + 1):
        divisors = get_divisors(n)
        tau_n = len(divisors)

        if tau_n >= 5:
            # Divisors are ordered: d1, d2, d3, d4, d5, ...
            # d1 is always 1.
            # a = second smallest divisor (d2)
            # b = third smallest divisor (d3)
            # c = fifth smallest divisor (d5)

            # Since tau_n >= 5, we are guaranteed to have at least 5 divisors (indices 0 to 4).
            a = divisors[1] # Second smallest
            b = divisors[2] # Third smallest
            c = divisors[4] # Fifth smallest

            # Check the condition: ab + ac + bc = n
            condition_met = (a * b + a * c + b * c == n)

            if condition_met:
                solutions.append({
                    'n': n,
                    'tau(n)': tau_n,
                    'a': a,
                    'b': b,
                    'c': c
                })

    return solutions

solutions = solve_problem()
print("Solutions found:")
if solutions:
    for sol in solutions:
        print(f"n = {sol['n']}, tau(n) = {sol['tau(n)']}, a={sol['a']}, b={sol['b']}, c={sol['c']}")
else:
    print("No solutions found up to n=500.")

def get_divisors(n):
    divs = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def count_divisors(n):
    if n == 1:
        return 1
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            count += 1
            if i * i != n:
                count += 1
    return count

def solve_problem(limit):
    solutions = []
    for n in range(1, limit + 1):
        tau_n = count_divisors(n)
        if tau_n < 5:
            continue

        divisors = get_divisors(n)

        # We require at least 5 divisors to have a, b, c defined.
        # Since tau_n >= 5, this is guaranteed.
        a = divisors[1] # Second smallest divisor (divisors[0] is 1)
        b = divisors[2] # Third smallest divisor
        c = divisors[4] # Fifth smallest divisor

        # Check the condition: n = ab + ac + bc
        if n == a*b + a*c + b*c:
            solutions.append((n, tau_n, a, b, c))

    return solutions

# Search up to N = 5000
results = solve_problem(5000)

# Format results for writing to notes
print("--- Solutions found up to N=5000 ---")
if not results:
    print("No solutions found.")
else:
    for n, tau, a, b, c in results:
        print(f"n = {n}, tau(n) = {tau}, a={a}, b={b}, c={c}")

    tau_values = sorted(list(set([r[1] for r in results])))
    print(f"All tau(n) values found: {tau_values}")
